{"query": "
-- ============================================================
-- STEP 2: Create the transfer_parts function
-- ============================================================
CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id   INTEGER,
    target_inventory_id   INTEGER,
    part_to_transfer_num  VARCHAR,
    color_to_transfer_id  INTEGER,
    quantity_to_transfer  INTEGER,
    transfer_reason       VARCHAR DEFAULT 'manual_transfer'
)
RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    -- Source inventory part record
    v_source_quantity   INTEGER;
    v_source_is_spare   BOOLEAN;

    -- Target inventory part record (may or may not exist)
    v_target_exists     BOOLEAN := FALSE;

    -- Result message
    v_result_message    TEXT;

    -- Error capture for audit log
    v_error_message     TEXT;
BEGIN

    -- ================================================================
    -- VALIDATION B (fast checks before locking anything)
    -- ================================================================

    -- B1: Prevent self-transfers
    IF source_inventory_id = target_inventory_id THEN
        v_error_message := 'Self-transfer not allowed: source and target inventory IDs are identical (' 
                           || source_inventory_id || ').';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- B2: Minimum quantity
    IF quantity_to_transfer < 1 THEN
        v_error_message := 'Invalid quantity: must transfer at least 1 part (requested: '
                           || quantity_to_transfer || ').';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- B3: Maximum quantity cap (500 per operation)
    IF quantity_to_transfer > 500 THEN
        v_error_message := 'Transfer quantity exceeds maximum limit of 500 parts per operation (requested: '
                           || quantity_to_transfer || ').';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- ================================================================
    -- VALIDATION A: Existence checks
    -- ================================================================

    -- A1: Verify source inventory exists
    IF NOT EXISTS (SELECT 1 FROM lego_inventories WHERE id = source_inventory_id) THEN
        v_error_message := 'Source inventory ID ' || source_inventory_id || ' does not exist in lego_inventories.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- A2: Verify target inventory exists
    IF NOT EXISTS (SELECT 1 FROM lego_inventories WHERE id = target_inventory_id) THEN
        v_error_message := 'Target inventory ID ' || target_inventory_id || ' does not exist in lego_inventories.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- A3: Verify part exists in lego_parts master catalogue
    IF NOT EXISTS (SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num) THEN
        v_error_message := 'Part "' || part_to_transfer_num || '" does not exist in lego_parts catalogue.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- A4: Verify color exists in lego_colors
    IF NOT EXISTS (SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id) THEN
        v_error_message := 'Color ID ' || color_to_transfer_id || ' does not exist in lego_colors.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- ================================================================
    -- STEP A: Lock both inventory_parts rows (prevent race conditions)
    --         Order locks by inventory_id to avoid deadlocks.
    -- ================================================================
    IF source_inventory_id < target_inventory_id THEN
        -- Lock source row first, then target
        PERFORM 1
        FROM lego_inventory_parts
        WHERE inventory_id = source_inventory_id
          AND part_num     = part_to_transfer_num
          AND color_id     = color_to_transfer_id
        FOR UPDATE;

        PERFORM 1
        FROM lego_inventory_parts
        WHERE inventory_id = target_inventory_id
          AND part_num     = part_to_transfer_num
          AND color_id     = color_to_transfer_id
        FOR UPDATE;
    ELSE
        -- Lock target row first, then source
        PERFORM 1
        FROM lego_inventory_parts
        WHERE inventory_id = target_inventory_id
          AND part_num     = part_to_transfer_num
          AND color_id     = color_to_transfer_id
        FOR UPDATE;

        PERFORM 1
        FROM lego_inventory_parts
        WHERE inventory_id = source_inventory_id
          AND part_num     = part_to_transfer_num
          AND color_id     = color_to_transfer_id
        FOR UPDATE;
    END IF;

    -- ================================================================
    -- Read source row (after lock acquired)
    -- ================================================================
    SELECT quantity, is_spare
      INTO v_source_quantity, v_source_is_spare
      FROM lego_inventory_parts
     WHERE inventory_id = source_inventory_id
       AND part_num     = part_to_transfer_num
       AND color_id     = color_to_transfer_id;

    -- A5: Source must actually hold this part/colour combination
    IF NOT FOUND THEN
        v_error_message := 'Part "' || part_to_transfer_num || '" with color_id ' || color_to_transfer_id
                           || ' not found in source inventory ' || source_inventory_id || '.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- A6: Sufficient stock (regular + spare counted together via the single row)
    IF v_source_quantity < quantity_to_transfer THEN
        v_error_message := 'Insufficient stock in source inventory ' || source_inventory_id
                           || ': available = ' || v_source_quantity
                           || ', requested = ' || quantity_to_transfer || '.';
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
            quantity_to_transfer, transfer_reason, 'failed', v_error_message
        );
        RAISE EXCEPTION '%', v_error_message;
    END IF;

    -- ================================================================
    -- STEP B: Update / delete source inventory row
    -- ================================================================
    IF v_source_quantity = quantity_to_transfer THEN
        -- Exact match → remove the row entirely
        DELETE FROM lego_inventory_parts
         WHERE inventory_id = source_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    ELSE
        -- Partial transfer → decrement quantity
        UPDATE lego_inventory_parts
           SET quantity = quantity - quantity_to_transfer
         WHERE inventory_id = source_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    END IF;

    -- ================================================================
    -- STEP C: Update or insert target inventory row
    -- ================================================================
    SELECT TRUE
      INTO v_target_exists
      FROM lego_inventory_parts
     WHERE inventory_id = target_inventory_id
       AND part_num     = part_to_transfer_num
       AND color_id     = color_to_transfer_id;

    IF v_target_exists IS TRUE THEN
        -- Part already exists in target → increment
        UPDATE lego_inventory_parts
           SET quantity = quantity + quantity_to_transfer
         WHERE inventory_id = target_inventory_id
           AND part_num     = part_to_transfer_num
           AND color_id     = color_to_transfer_id;
    ELSE
        -- New part in target → insert, preserving is_spare from source
        INSERT INTO lego_inventory_parts (inventory_id, part_num, color_id, quantity, is_spare)
        VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id,
                quantity_to_transfer, v_source_is_spare);
    END IF;

    -- ================================================================
    -- STEP D: Audit log — successful transfer
    -- ================================================================
    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id, part_num, color_id,
        quantity_transferred, transfer_reason, transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id, part_to_transfer_num, color_to_transfer_id,
        quantity_to_transfer, transfer_reason, 'success', NULL
    );

    -- ================================================================
    -- Build and return success message
    -- ================================================================
    v_result_message :=
        'Successfully transferred ' || quantity_to_transfer || ' parts'
        || ' (' || part_to_transfer_num || ', color_id: ' || color_to_transfer_id || ')'
        || ' from inventory ' || source_inventory_id
        || ' to inventory '   || target_inventory_id
        || '. Reason: '       || transfer_reason;

    RETURN v_result_message;

EXCEPTION
    -- Re-raise any RAISE EXCEPTION that already inserted its own log row
    WHEN OTHERS THEN
        RAISE;
END;
$$;
"}

