-- ============================================================
-- VERIFY C: Confirm failed transfers are logged by wrapping
-- each call in a savepoint so the outer transaction survives.
-- ============================================================
DO $$
BEGIN
    -- Failed Test 3: quantity > 500
    BEGIN
        PERFORM transfer_parts(14469, 14686, '3024', 15, 2000, 'large_transfer');
    EXCEPTION WHEN OTHERS THEN
        -- exception already logged inside the function before RAISE
        RAISE NOTICE 'Test 3 caught: %', SQLERRM;
    END;

    -- Failed Test 4: self-transfer
    BEGIN
        PERFORM transfer_parts(14469, 14469, '3024', 15, 10, 'self_transfer');
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Test 4 caught: %', SQLERRM;
    END;
END;
$$;
"}

